import{_ as a,o as n,c as t,a2 as s}from"./chunks/framework.CYj0tiXz.js";const m=JSON.parse('{"title":"Changelog","description":"BlendSDK release notes and version history","frontmatter":{"title":"Changelog","description":"BlendSDK release notes and version history"},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1793351544000}'),o={name:"reference/changelog.md"};function i(r,e,l,d,c,h){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="blendsdk-v5-68-0-—-release-notes" tabindex="-1">BlendSDK v5.68.0 — Release Notes <a class="header-anchor" href="#blendsdk-v5-68-0-—-release-notes" aria-label="Permalink to &quot;BlendSDK v5.68.0 — Release Notes&quot;">​</a></h1><p><strong>Released</strong>: 2026-10-29</p><p>We are excited to announce the release of BlendSDK version 5.68.0! This update includes a variety of improvements that enhance the functionality, security, and usability of our software development kit.</p><p>In this version, we have made key updates across several packages that will provide developers with a smoother experience and ensure that projects utilizing our SDK remain robust and secure. The updates also improve the overall documentation, making it easier for users to access the information they need.</p><p>Here are some key highlights from this release:</p><h3 id="api-client-enhancements" tabindex="-1">API Client Enhancements <a class="header-anchor" href="#api-client-enhancements" aria-label="Permalink to &quot;API Client Enhancements&quot;">​</a></h3><p>The API Client has had its dependencies updated and improved documentation added, providing clearer guidance on using the SDK. Additionally, a new typed HTTP client runtime has been introduced, further simplifying development processes.</p><h3 id="authorization-improvements" tabindex="-1">Authorization Improvements <a class="header-anchor" href="#authorization-improvements" aria-label="Permalink to &quot;Authorization Improvements&quot;">​</a></h3><p>Enhancements to the authorization package ensure that user claims are processed more securely and efficiently. This includes better handling of authorization examples and improved testing for validation scenarios.</p><h3 id="blendscript-refinements" tabindex="-1">BlendScript Refinements <a class="header-anchor" href="#blendscript-refinements" aria-label="Permalink to &quot;BlendScript Refinements&quot;">​</a></h3><p>There have been updates to BlendScript for more accurate diagnostics and better content generation, ensuring that developers have access to the right tools for their projects.</p><h3 id="documentation-enhancements" tabindex="-1">Documentation Enhancements <a class="header-anchor" href="#documentation-enhancements" aria-label="Permalink to &quot;Documentation Enhancements&quot;">​</a></h3><p>We have refreshed our documentation across several components of the SDK, targeting improved clarity and ease of understanding. This will be invaluable for both new and existing users.</p><h3 id="general-security-updates" tabindex="-1">General Security Updates <a class="header-anchor" href="#general-security-updates" aria-label="Permalink to &quot;General Security Updates&quot;">​</a></h3><p>Security has been a focus in this release. Implementation of new hardening measures ensures that user data remains safe while interacting with the SDK.</p><h3 id="miscellaneous-updates" tabindex="-1">Miscellaneous Updates <a class="header-anchor" href="#miscellaneous-updates" aria-label="Permalink to &quot;Miscellaneous Updates&quot;">​</a></h3><p>We have also worked on performance improvements, streamlined installation commands, and made several packaging updates across various components, aiming for a more cohesive and efficient development experience.</p><p>These improvements reflect our commitment to continually refine and enhance the BlendSDK, ensuring our users have the best tools available for developing their applications. We encourage all users to update to version 5.68.0 to take advantage of these enhancements!</p><hr><p><em>Install: <code>npm install blendsdk@5</code></em><em>Full changelog: See individual package CHANGELOG.md files</em></p>',20)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
